package com.vault.service;
import com.vault.dto.*;import com.vault.entity.*;import com.vault.repository.*;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.util.*;import java.util.stream.Collectors;
@Service public class KeyService{private final ApiKeyRepository keys;private final ActivityLogRepository logs;private final AccountService accounts;private final CryptoService crypto;private final PasswordEncoder passwords;public KeyService(ApiKeyRepository k,ActivityLogRepository l,AccountService a,CryptoService c,PasswordEncoder p){keys=k;logs=l;accounts=a;crypto=c;passwords=p;}
 private ApiKey owned(UUID id,String email){User u=accounts.current(email);return keys.findByIdAndUserId(id,u.getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"API key not found"));}private void log(User u,ApiKey k,String action,String desc){logs.save(new ActivityLog(u,k,action,desc,null));}private Views.KeyView view(ApiKey k){return Views.KeyView.from(k);}
 @Transactional(readOnly=true)public List<Views.KeyView> list(String email){return keys.findByUserIdOrderByCreatedAtDesc(accounts.current(email).getId()).stream().map(this::view).toList();}
 @Transactional public Views.KeyView create(String email,Requests.CreateKey x){User u=accounts.current(email);ApiKey k=keys.save(new ApiKey(u,x.serviceName().trim(),x.keyName().trim(),crypto.encrypt(x.apiKey()),x.environment(),x.description(),x.expiresAt()));log(u,k,"CREATE","Added "+k.getServiceName()+" "+k.getEnvironment()+" key");return view(k);}
 @Transactional(readOnly=true)public Views.KeyView get(String email,UUID id){return view(owned(id,email));}
 @Transactional public Views.KeyView update(String email,UUID id,Requests.UpdateKey x){ApiKey k=owned(id,email);k.setServiceName(x.serviceName());k.setKeyName(x.keyName());k.setEnvironment(x.environment());k.setDescription(x.description());k.setExpiresAt(x.expiresAt());log(k.getUser(),k,"UPDATE","Updated "+k.getServiceName()+" key metadata");return view(k);}
 @Transactional public String reveal(String email,UUID id,Requests.Reveal x){User u=accounts.current(email);if(!passwords.matches(x.password(),u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Password confirmation failed");ApiKey k=owned(id,email);if(!"ACTIVE".equals(k.effectiveStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only active keys can be revealed");k.setLastUsedAt(Instant.now());log(u,k,"REVEAL","Revealed "+k.getServiceName()+" "+k.getEnvironment()+" key");return crypto.decrypt(k.getEncryptedKey());}
 @Transactional public Views.KeyView rotate(String email,UUID id,Requests.Rotate x){ApiKey k=owned(id,email);if(!"ACTIVE".equals(k.effectiveStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only active keys can be rotated");k.setStatus("REVOKED");log(k.getUser(),k,"ROTATE","Rotated "+k.getServiceName()+" "+k.getEnvironment()+" key");ApiKey replacement=keys.save(new ApiKey(k.getUser(),k.getServiceName(),k.getKeyName(),crypto.encrypt(x.apiKey()),k.getEnvironment(),k.getDescription(),k.getExpiresAt()));log(k.getUser(),replacement,"CREATE","Added replacement for "+k.getKeyName());return view(replacement);}
 @Transactional public void revoke(String email,UUID id){ApiKey k=owned(id,email);k.setStatus("REVOKED");log(k.getUser(),k,"REVOKE","Revoked "+k.getServiceName()+" "+k.getEnvironment()+" key");}
 @Transactional public void delete(String email,UUID id){ApiKey k=owned(id,email);log(k.getUser(),null,"DELETE","Deleted "+k.getServiceName()+" "+k.getKeyName());logs.detachKey(k);keys.delete(k);}
 @Transactional public void copy(String email,UUID id){ApiKey k=owned(id,email);log(k.getUser(),k,"COPY","Copied "+k.getServiceName()+" "+k.getEnvironment()+" key");}
 @Transactional(readOnly=true)public Views.Stats stats(String email){List<ApiKey> all=keys.findByUserIdOrderByCreatedAtDesc(accounts.current(email).getId());Instant now=Instant.now(),limit=now.plus(Duration.ofDays(30));return new Views.Stats(all.size(),all.stream().filter(k->"ACTIVE".equals(k.effectiveStatus())).count(),all.stream().filter(k->"ACTIVE".equals(k.effectiveStatus())&&k.getExpiresAt()!=null&&!k.getExpiresAt().isBefore(now)&&k.getExpiresAt().isBefore(limit)).count(),all.stream().map(ApiKey::getServiceName).collect(Collectors.toSet()).size());}
}
